/**
 * Typed accessors for the Cloudflare Workers AI model catalogue.
 *
 * The underlying data lives in ./data/models.json, regenerated by
 * scripts/sync-cloudflare-models.ts. We parse it through Zod at module load
 * so that a shape mismatch fails the build immediately instead of surfacing
 * as a runtime bug somewhere downstream.
 */
import raw from "./data/models.json";
import { ModelsFileSchema, type ModelInfo, type ModelTask } from "./schema";

const parsed = ModelsFileSchema.safeParse(raw);
if (!parsed.success) {
  const issues = parsed.error.issues
    .map((i) => `  - ${i.path.join(".") || "<root>"}: ${i.message}`)
    .join("\n");
  throw new Error(
    `[generated/models] models.json failed schema validation.\n` +
      `Run \`pnpm sync:models\` to regenerate, and verify the sync script ` +
      `matches the current version of src/generated/schema.ts.\n${issues}`,
  );
}

const file = parsed.data;

/** Timestamp of the last successful sync. */
export const MODELS_GENERATED_AT: string = file.generatedAt;

/** Full model catalogue. */
export const MODELS: readonly ModelInfo[] = file.models;

export type FreeTextModel = ModelInfo & { task: "text-generation" };
export type FreeImageModel = ModelInfo & { task: "text-to-image" };

function isFreeTextModel(m: ModelInfo): m is FreeTextModel {
  return (
    m.capabilities.requireWorkersPaid === false && m.task === "text-generation"
  );
}

function isFreeImageModel(m: ModelInfo): m is FreeImageModel {
  return (
    m.capabilities.requireWorkersPaid === false && m.task === "text-to-image"
  );
}

/** Free tier available models. */
export const FREE_MODELS: readonly ModelInfo[] = MODELS.filter(
  (m) => m.capabilities.requireWorkersPaid === false,
);

export const FREE_TEXT_GENERATION_MODELS: readonly FreeTextModel[] =
  MODELS.filter(isFreeTextModel);

export const FREE_TEXT_TO_IMAGE_MODELS: readonly FreeImageModel[] =
  MODELS.filter(isFreeImageModel);

export const FREE_MODEL_BY_NAME: ReadonlyMap<string, ModelInfo> = new Map(
  FREE_MODELS.map((m) => [m.name, m]),
);

export const FREE_MODEL_BY_ID: ReadonlyMap<string, ModelInfo> = new Map(
  FREE_MODELS.map((m) => [m.id, m]),
);

export type { ModelInfo, ModelTask };
